INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Berapa jumlah rukun sholat menurut mazhab Syafi''i?', '["13", "6", "14", "17"]', '13', 'Mazhab Syafi''i menghitung 13 rukun, atau 17 jika setiap tuma''ninah dihitung terpisah.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Manakah dari berikut ini yang TIDAK termasuk syarat sah sholat?', '["Membaca surat pendek setelah Al-Fatihah", "Sudah masuk waktu sholat", "Suci dari hadats kecil dan besar", "Menghadap kiblat"]', 'Membaca surat pendek setelah Al-Fatihah', 'Membaca surat pendek hukumnya sunnah, bukan syarat sah. Syarat sah meliputi waktu, suci dari hadats dan najis, menutup aurat, dan menghadap kiblat.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Dalam mazhab Syafi''i, bacaan basmalah pada Al-Fatihah hukumnya?', '["Wajib dibaca, termasuk ayat pertama", "Sunnah, boleh ditinggalkan", "Makruh dibaca keras", "Bukan bagian dari bacaan sholat"]', 'Wajib dibaca, termasuk ayat pertama', 'Menurut mazhab Syafi''i, basmalah termasuk bagian dari Al-Fatihah sehingga wajib dibaca.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Manakah berikut ini yang membatalkan sholat?', '["Berbicara dengan sengaja di luar bacaan sholat", "Membaca doa iftitah", "Duduk tawarruk pada tahiyat akhir", "Mengangkat tangan saat takbiratul ihram"]', 'Berbicara dengan sengaja di luar bacaan sholat', 'Berbicara dengan sengaja di luar bacaan sholat termasuk hal yang membatalkan sholat.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Menurut mazhab Syafi''i, salam pertama hukumnya ____, sedangkan salam kedua ____.', '["rukun; sunnah", "sunnah; rukun", "rukun; rukun", "sunnah; sunnah"]', 'rukun; sunnah', 'Salam pertama wajib (rukun), sedangkan salam kedua sunnah menurut mazhab Maliki dan Syafi''i.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Pada rakaat kedua sholat Subuh, mazhab Syafi''i menyunnahkan bacaan tambahan setelah i''tidal, yaitu doa…', '["Qunut", "Iftitah", "Istiftah", "Tasyahud"]', 'Qunut', 'Mazhab Syafi''i menyunnahkan doa qunut pada rakaat kedua sholat Subuh, setelah i''tidal.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Posisi duduk pada tahiyat akhir menurut mazhab Syafi''i disebut…', '["Tawarruk", "Iftirasy", "Bersila", "Duduk di atas kedua tumit"]', 'Tawarruk', 'Duduk tahiyat akhir dalam mazhab Syafi''i memakai posisi tawarruk, berbeda dengan tahiyat awal yang memakai iftirasy.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Posisi duduk pada tahiyat awal (sholat 3 atau 4 rakaat) menurut mazhab Syafi''i disebut…', '["Iftirasy", "Tawarruk", "Bersila", "Berbaring miring"]', 'Iftirasy', 'Tahiyat awal memakai posisi iftirasy, yaitu duduk di atas telapak kaki kiri dengan kaki kanan ditegakkan.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Menurut mazhab Hanafi, jumlah rukun sholat ada…', '["6", "13", "14", "17"]', '6', 'Jumlah rukun berbeda karena cara mengelompokkan: Hanafi 6, Maliki 14, Syafi''i 13, Hambali 14.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Apa arti tuma''ninah, yang menjadi bagian dari rukun rukuk, i''tidal, sujud, dan duduk di antara dua sujud?', '["Diam atau tenang sejenak dalam gerakan itu", "Mempercepat gerakan sholat", "Membaca doa dengan suara keras", "Mengulang gerakan dua kali"]', 'Diam atau tenang sejenak dalam gerakan itu', 'Tuma''ninah artinya diam sejenak dengan tenang pada setiap rukun gerakan, sebelum berpindah ke gerakan berikutnya.', 'manual', 1);
INSERT OR IGNORE INTO questions (prompt, options, correct, explain, kind, active) VALUES ('Dalam sholat berjamaah menurut mazhab Syafi''i, makmum WAJIB menambahkan kata “ma''muuman” pada niatnya, sedangkan imam…', '["tidak wajib menambahkan kata “imaaman”", "juga wajib menambahkan kata “imaaman”", "justru dilarang berniat berjamaah", "harus mengikuti niat makmum"]', 'tidak wajib menambahkan kata “imaaman”', 'Makmum wajib berniat ma''muuman, sedangkan imam tidak wajib menambahkan kata imaaman — tanpa itu sholatnya tetap sah, hanya dianggap sholat sendirian, bukan berjamaah.', 'manual', 1);
